def _skip_member(
    obj: Any, name: str, obj_type: _AutodocObjType, *, events: EventManager
) -> bool:
    try:
        return events.emit_firstresult(
            'autodoc-skip-member', obj_type, name, obj, False, {}
        )
    except Exception as exc:
        logger.warning(
            __(
                'autosummary: failed to determine %r to be documented, '
                'the following exception was raised:\n%s'
            ),
            name,
            exc,
            type='autosummary',
        )
        return False


def _get_class_members(obj: Any) -> dict[str, Any]:
    """Get members and attributes of target class."""
    # TODO: Simplify
    # the members directly defined in the class
    obj_dict = safe_getattr(obj, '__dict__', {})

    members_simpler: dict[str, Any] = {}

    # enum members
    if isenumclass(obj):
        for name, defining_class, value in _filter_enum_dict(
            obj, safe_getattr, obj_dict
        ):
            # the order of occurrence of *name* matches obj's MRO,
            # allowing inherited attributes to be shadowed correctly
            if unmangled := unmangle(defining_class, name):
                members_simpler[unmangled] = value

    # members in __slots__
    try:
        subject___slots__ = getslots(obj)
        if subject___slots__:
            for name in subject___slots__:
                members_simpler[name] = SLOTS_ATTR
    except (TypeError, ValueError):
        pass

    # other members
    for name in dir(obj):
        try:
            value = safe_getattr(obj, name)
            if ismock(value):
                value = undecorate(value)

            unmangled = unmangle(obj, name)
            if unmangled and unmangled not in members_simpler:
                members_simpler[unmangled] = value
        except AttributeError:
            continue

    try:
        for cls in getmro(obj):
            try:
                modname = safe_getattr(cls, '__module__')
                qualname = safe_getattr(cls, '__qualname__')
            except AttributeError:
                qualname = None
                analyzer = None
            else:
                try:
                    analyzer = ModuleAnalyzer.for_module(modname)
                    analyzer.analyze()
                except PycodeError:
                    analyzer = None

            # annotation only member (ex. attr: int)
            for name in getannotations(cls):
                unmangled = unmangle(cls, name)
                if unmangled and unmangled not in members_simpler:
                    members_simpler[unmangled] = INSTANCE_ATTR

            # append or complete instance attributes (cf. self.attr1) if analyzer knows
            if analyzer:
                for ns, name in analyzer.attr_docs:
                    if ns == qualname and name not in members_simpler:
                        # otherwise unknown instance attribute
                        members_simpler[name] = INSTANCE_ATTR
    except AttributeError:
        pass

    return members_simpler


def _get_module_members(obj: Any, *, config: Config) -> dict[str, Any]:
    members = {}
    for name in members_of(obj, config=config):
        try:
            members[name] = safe_getattr(obj, name)
        except AttributeError:
            continue
    return members


def _get_all_members(
    obj_type: _AutodocObjType, obj: Any, *, config: Config
) -> dict[str, Any]:
    if obj_type == 'module':
        return _get_module_members(obj, config=config)
    elif obj_type == 'class':
        return _get_class_members(obj)
    return {}


def _get_members(
    obj_type: _AutodocObjType,
    obj: Any,
    types: set[str],
    *,
    config: Config,
    events: EventManager,
    include_public: Set[str] = frozenset(),
    imported: bool = True,
) -> tuple[list[str], list[str]]:
    items: list[str] = []
    public: list[str] = []

    all_members = _get_all_members(obj_type, obj, config=config)
    for name, value in all_members.items():
        obj_type = _get_documenter(value, obj)
        if obj_type in types:
            # skip imported members if expected
            if imported or getattr(value, '__module__', None) == obj.__name__:
                skipped = _skip_member(value, name, obj_type, events=events)
                if skipped is True:
                    pass
                elif skipped is False:
                    # show the member forcedly
                    items.append(name)
                    public.append(name)
                else:
                    items.append(name)
                    if name in include_public or not name.startswith('_'):
                        # considers member as public
                        public.append(name)
    return public, items


def _get_module_attrs(name: str, members: Any) -> tuple[list[str], list[str]]:
    """Find module attributes with docstrings."""
    attrs, public = [], []
    try:
        analyzer = ModuleAnalyzer.for_module(name)
        attr_docs = analyzer.find_attr_docs()
        for namespace, attr_name in attr_docs:
            if not namespace and attr_name in members:
                attrs.append(attr_name)
                if not attr_name.startswith('_'):
                    public.append(attr_name)
    except PycodeError:
        pass  # give up if ModuleAnalyzer fails to parse code
    return public, attrs


def _get_modules(
    obj: Any,
    *,
    skip: Sequence[str],
    name: str,
    public_members: Sequence[str] | None = None,
) -> tuple[list[str], list[str]]:
    items: list[str] = []
    public: list[str] = []
    for _, modname, _ispkg in pkgutil.iter_modules(obj.__path__):
        if modname in skip:
            # module was overwritten in __init__.py, so not accessible
            continue
        fullname = f'{name}.{modname}'
        try:
            module = import_module(fullname)
        except ImportError:
            pass
        else:
            if module and hasattr(module, '__sphinx_mock__'):
                continue

        items.append(modname)
        if public_members is not None:
            if modname in public_members:
                public.append(modname)
        else:
            if not modname.startswith('_'):
                public.append(modname)
    return public, items


def generate_autosummary_docs(
    sources: list[str],
    output_dir: str | os.PathLike[str] | None = None,
    suffix: str = '.rst',
    base_path: str | os.PathLike[str] | None = None,
    imported_members: bool = False,
    app: Sphinx | None = None,
    overwrite: bool = True,
    encoding: str = 'utf-8',
) -> list[Path]:
    """Generate autosummary documentation for the given sources.

    :returns: list of generated files (both new and existing ones)
    """
    assert app is not None, 'app is required'

    showed_sources = sorted(sources)
    if len(showed_sources) > 20:
        showed_sources = [*showed_sources[:10], '...', *showed_sources[-10:]]
    logger.info(
        __('[autosummary] generating autosummary for: %s'), ', '.join(showed_sources)
    )

    if output_dir:
        logger.info(__('[autosummary] writing to %s'), output_dir)

    if base_path is not None:
        base_path = Path(base_path)
        source_paths = [base_path / filename for filename in sources]
    else:
        source_paths = list(map(Path, sources))

    template = AutosummaryRenderer(app)

    # read
    items = find_autosummary_in_files(source_paths)

    # keep track of new files
    new_files: list[Path] = []
    all_files: list[Path] = []

    filename_map = app.config.autosummary_filename_map

    # write
    for entry in sorted(set(items), key=str):
        if entry.path is None:
            # The corresponding autosummary:: directive did not have
            # a :toctree: option
            continue

        path = output_dir or Path(entry.path).resolve()
        ensuredir(path)

        try:
            name, obj, parent, modname = import_by_name(entry.name)
            qualname = name.replace(modname + '.', '')
        except ImportExceptionGroup as exc:
            try:
                # try to import as an instance attribute
                name, obj, parent, modname = import_ivar_by_name(entry.name)

            return NotImplemented
        return (
            self.name == other.name
            and self.target_uri == other.target_uri
            and self.locations == other.locations
        )

    def __hash__(self) -> int:
        return hash((self.name, self.target_uri, self.locations))

    def __setattr__(self, key: str, value: Any) -> NoReturn:
        msg = f'{self.__class__.__name__} is immutable'
        raise AttributeError(msg)

    def __delattr__(self, key: str) -> NoReturn:
        msg = f'{self.__class__.__name__} is immutable'
        raise AttributeError(msg)


class InventoryAdapter:
    """Inventory adapter for environment"""

class IntersphinxDispatcher(CustomReSTDispatcher):
    """Custom dispatcher for external role.

    This enables :external:***:/:external+***: roles on parsing reST document.
    """

    def role(
        self,
        role_name: str,
        language_module: ModuleType,
        lineno: int,
        reporter: Reporter,
    ) -> tuple[RoleFunction, list[system_message]]:
        if len(role_name) > 9 and role_name.startswith(('external:', 'external+')):
            return IntersphinxRole(role_name), []
        else:
            return super().role(role_name, language_module, lineno, reporter)


class IntersphinxRole(SphinxRole):
    # group 1: just for the optionality of the inventory name
    # group 2: the inventory name (optional)
    # group 3: the domain:role or role part
    _re_inv_ref = re.compile(r'(\+([^:]+))?:(.*)')

    def __init__(self, orig_name: str) -> None:
        self.orig_name = orig_name

    def run(self) -> tuple[list[Node], list[system_message]]:
        assert self.name == self.orig_name.lower()
        inventory, name_suffix = self.get_inventory_and_name_suffix(self.orig_name)
        resolve_self = self.env.config.intersphinx_resolve_self
        self_referential = bool(resolve_self) and resolve_self == inventory

        if not self_referential:
            if inventory and not inventory_exists(self.env, inventory):
                self._emit_warning(
                    __('inventory for external cross-reference not found: %r'),
                    inventory,
                )
                return [], []

        domain_name, role_name = self._get_domain_role(name_suffix)

        if role_name is None:
            self._emit_warning(
                __('invalid external cross-reference suffix: %r'), name_suffix
            )
            return [], []

        # attempt to find a matching role function
        role_func: RoleFunction | None

        if domain_name is not None:
            # the user specified a domain, so we only check that
            if domain_name not in self.env.domains:
                self._emit_warning(
                    __('domain for external cross-reference not found: %r'), domain_name
                )
                return [], []
            domain = self.env.domains[domain_name]
            role_func = domain.roles.get(role_name)
            if role_func is None:
                msg = 'role for external cross-reference not found in domain %r: %r'
                object_types = domain.object_types.get(role_name)
                if object_types is not None and object_types.roles:
                    self._emit_warning(
                        __(f'{msg} (perhaps you meant one of: %s)'),
                        domain_name,
                        role_name,
                        self._concat_strings(object_types.roles),
                    )
                else:
                    self._emit_warning(__(msg), domain_name, role_name)
                return [], []

        else:
            # the user did not specify a domain,
            # so we check first the default (if available) then standard domains
            default_domain = self.env.current_document.default_domain
            std_domain = self.env.domains.standard_domain
            domains: Sequence[Domain]
            if default_domain is None or std_domain == default_domain:
                domains = (std_domain,)
            else:
                domains = (default_domain, std_domain)

            role_func = None
            for domain in domains:
                role_func = domain.roles.get(role_name)

                if role_func is not None:
                    domain_name = domain.name
                    break

            if role_func is None or domain_name is None:
                domains_str = self._concat_strings(domain.name for domain in domains)
                msg = 'role for external cross-reference not found in domains %s: %r'
                possible_roles: set[str] = {
                    f'{domain.name}:{r}'
                    for domain in domains
                    if (object_types := domain.object_types.get(role_name))
                    for r in object_types.roles
                }
                if possible_roles:
                    msg = f'{msg} (perhaps you meant one of: %s)'
                    self._emit_warning(
                        __(msg),
                        domains_str,
                        role_name,
                        self._concat_strings(possible_roles),
                    )
                else:
                    self._emit_warning(__(msg), domains_str, role_name)
                return [], []

        result, messages = role_func(
            f'{domain_name}:{role_name}',
            self.rawtext,
            self.text,
            self.lineno,
            self.inliner,
            self.options,
            self.content,
        )

        if not self_referential:
            # We do the intersphinx resolution by inserting our
            # 'intersphinx' and 'inventory' attributes into the nodes.
            # Only do this when it is an external reference.
            for node in result:
                if isinstance(node, pending_xref):
                    node['intersphinx'] = True
                    node['inventory'] = inventory

        return result, messages

    def get_inventory_and_name_suffix(self, name: str) -> tuple[str | None, str]:
        """Extract an inventory name (if any) and ``domain+name`` suffix from a role *name*.
        and the domain+name suffix.

        The role name is expected to be of one of the following forms:

        - ``external+inv:name`` -- explicit inventory and name, any domain.
        - ``external+inv:domain:name`` -- explicit inventory, domain and name.
        - ``external:name`` -- any inventory and domain, explicit name.
        - ``external:domain:name`` -- any inventory, explicit domain and name.
        """
        assert name.startswith('external'), name
        suffix = name[9:]
        if name[8] == '+':
            inv_name, _, suffix = suffix.partition(':')
            return inv_name, suffix
        elif name[8] == ':':
            return None, suffix
        else:
            msg = f'Malformed :external: role name: {name}'
            raise ValueError(msg)

    def _get_domain_role(self, name: str) -> tuple[str | None, str | None]:
        """Convert the *name* string into a domain and a role name.

        - If *name* contains no ``:``, return ``(None, name)``.
        - If *name* contains a single ``:``, the domain/role is split on this.
        - If *name* contains multiple ``:``, return ``(None, None)``.
        """
        names = name.split(':')
        if len(names) == 1:
            return None, names[0]
        elif len(names) == 2:
            return names[0], names[1]
        else:
            return None, None

    def _emit_warning(self, msg: str, /, *args: Any) -> None:
        LOGGER.warning(
            msg,
            *args,
            type='intersphinx',
            subtype='external',
            location=(self.env.current_document.docname, self.lineno),
        )

    def _concat_strings(self, strings: Iterable[str]) -> str:
        return ', '.join(f'{s!r}' for s in sorted(strings))

    # deprecated methods

    def get_role_name(self, name: str) -> tuple[str, str] | None:
        _deprecation_warning(
            __name__, f'{self.__class__.__name__}.get_role_name', '', remove=(9, 0)
        )
        names = name.split(':')
        if len(names) == 1:
            # role
            if (domain := self.env.current_document.default_domain) is not None:
                domain_name = domain.name
            else:
                domain_name = None
            role = names[0]
        elif len(names) == 2:
            # domain:role:
            domain_name, role = names
        else:
            return None

        if domain_name and self.is_existent_role(domain_name, role):
            return domain_name, role
        elif self.is_existent_role('std', role):
            return 'std', role
        else:
            return None

    def is_existent_role(self, domain_name: str, role_name: str) -> bool:
        _deprecation_warning(
            __name__, f'{self.__class__.__name__}.is_existent_role', '', remove=(9, 0)
        )
        try:
            domain = self.env.domains[domain_name]
        except KeyError:
            return False
        else:
            return role_name in domain.roles

    def invoke_role(
        self, role: tuple[str, str]
    ) -> tuple[list[Node], list[system_message]]:
        """Invoke the role described by a ``(domain, role name)`` pair."""
        _deprecation_warning(
            __name__, f'{self.__class__.__name__}.invoke_role', '', remove=(9, 0)
        )
        domain = self.env.get_domain(role[0])
        if domain:
            role_func = domain.role(role[1])
            assert role_func is not None

            return role_func(
                ':'.join(role),
                self.rawtext,
                self.text,
                self.lineno,
                self.inliner,
                self.options,
                self.content,
            )
        else:
            return [], []


class IntersphinxRoleResolver(ReferencesResolver):
    """pending_xref node resolver for intersphinx role.

    This resolves pending_xref nodes generated by :intersphinx:***: role.
    """

    default_priority = ReferencesResolver.default_priority - 1

    def run(self, **kwargs: Any) -> None:
        for node in self.document.findall(pending_xref):
            if 'intersphinx' not in node:
                continue
            contnode = cast('nodes.TextElement', node[0].deepcopy())
            inv_name = node['inventory']
            if inv_name is not None:
                assert inventory_exists(self.env, inv_name)
                newnode = resolve_reference_in_inventory(
                    self.env, inv_name, node, contnode
                )
            else:
                newnode = resolve_reference_any_inventory(
                    self.env, False, node, contnode
                )
            if newnode is None:
                typ = node['reftype']
                msg = __('external %s:%s reference target not found: %s') % (
                    node['refdomain'],
                    typ,
                    node['reftarget'],
                )
                LOGGER.warning(msg, location=node, type='ref', subtype=typ)
                node.replace_self(contnode)
            else:
                node.replace_self(newnode)

    if not colon or not _desc:
        _type, _desc = _desc, _type
        _desc += colon
    _descs = [_desc, *self._dedent(self._consume_to_end())]
    _descs = self.__class__(_descs, self._config).lines()
    return _type, _descs

def _consume_returns_section(
    self, preprocess_types: bool = False
) -> list[tuple[str, str, list[str]]]:
    lines = self._dedent(self._consume_to_next_section())
    if lines:
        before, colon, after = self._partition_field_on_colon(lines[0])
        _name, _type, _desc = '', '', lines

        if colon:
            if after:
                _desc = [after, *lines[1:]]
            else:
                _desc = lines[1:]

            _type = before

        if _type and preprocess_types and self._config.napoleon_preprocess_types:
            _type = _convert_type_spec(
                _type,
                translations=self._config.napoleon_type_aliases or {},
                debug_location=self._get_location(),
            )

        _desc = self.__class__(_desc, self._config).lines()
        return [(_name, _type, _desc)]
    else:
        return []

def _consume_usage_section(self) -> list[str]:
    lines = self._dedent(self._consume_to_next_section())
    return lines

def _consume_section_header(self) -> str:
    section = self._lines.next()
    stripped_section = section.strip(':')
    if stripped_section.lower() in self._sections:
        section = stripped_section
    return section

def _consume_to_end(self) -> list[str]:
    lines = []
    while self._lines:
        lines.append(self._lines.next())
    return lines

def _consume_to_next_section(self) -> list[str]:
    self._consume_empty()
    lines = []
    while not self._is_section_break():
        lines.append(self._lines.next())
    return lines + self._consume_empty()

def _dedent(self, lines: list[str], full: bool = False) -> list[str]:
    if full:
        return [line.lstrip() for line in lines]
    else:
        min_indent = self._get_min_indent(lines)
        return [line[min_indent:] for line in lines]

def _escape_args_and_kwargs(self, name: str) -> str:
    if name.endswith('_') and getattr(
        self._config, 'strip_signature_backslash', False
    ):
        name = name[:-1] + r'\_'

    if name[:2] == '**':
        return r'\*\*' + name[2:]
    elif name[:1] == '*':
        return r'\*' + name[1:]
    else:
        return name

def _fix_field_desc(self, desc: list[str]) -> list[str]:
    if self._is_list(desc):
        desc = ['', *desc]
    elif desc[0].endswith('::'):
        desc_block = desc[1:]
        indent = self._get_indent(desc[0])
        block_indent = self._get_initial_indent(desc_block)
        if block_indent > indent:
            desc = ['', *desc]
        else:
            desc = ['', desc[0], *self._indent(desc_block, 4)]
    return desc

def _format_admonition(self, admonition: str, lines: list[str]) -> list[str]:
    lines = self._strip_empty(lines)
    if len(lines) == 1:
        return [f'.. {admonition}:: {lines[0].strip()}', '']
    elif lines:
        lines = self._indent(self._dedent(lines), 3)
        return [f'.. {admonition}::', '', *lines, '']
    else:
        return [f'.. {admonition}::', '']

def _format_block(
    self,
    prefix: str,
    lines: list[str],
    padding: str | None = None,
) -> list[str]:
    if lines:
        if padding is None:
            padding = ' ' * len(prefix)
        result_lines = []
        for i, line in enumerate(lines):
            if i == 0:
                result_lines.append((prefix + line).rstrip())
            elif line:
                result_lines.append(padding + line)
            else:
                result_lines.append('')
        return result_lines
    else:
        return [prefix]

def _format_docutils_params(
    self,
    fields: list[tuple[str, str, list[str]]],
    field_role: str = 'param',
    type_role: str = 'type',
) -> list[str]:
    lines = []
    for _name, _type, _desc in fields:
        _desc = self._strip_empty(_desc)
        if any(_desc):
            _desc = self._fix_field_desc(_desc)
            field = f':{field_role} {_name}: '
            lines.extend(self._format_block(field, _desc))
        else:
            lines.append(f':{field_role} {_name}:')

        if _type:
            lines.append(f':{type_role} {_name}: {_type}')
    return [*lines, '']

def _format_field(self, _name: str, _type: str, _desc: list[str]) -> list[str]:
    _desc = self._strip_empty(_desc)
    has_desc = any(_desc)
    separator = ' -- ' if has_desc else ''
    if _name:
        if _type:
            if '`' in _type:
                field = f'**{_name}** ({_type}){separator}'
            else:
                field = f'**{_name}** (*{_type}*){separator}'
        else:
            field = f'**{_name}**{separator}'
    elif _type:
        if '`' in _type:
            field = f'{_type}{separator}'
        else:
            field = f'*{_type}*{separator}'
    else:
        field = ''

    if has_desc:
        _desc = self._fix_field_desc(_desc)
        if _desc[0]:
            return [field + _desc[0], *_desc[1:]]
        else:
            return [field, *_desc]
    else:
        return [field]

def _format_fields(
    self,
    field_type: str,
    fields: list[tuple[str, str, list[str]]],
) -> list[str]:
    field_type = f':{field_type.strip()}:'
    padding = ' ' * len(field_type)
    multi = len(fields) > 1
    lines: list[str] = []
    for _name, _type, _desc in fields:
        field = self._format_field(_name, _type, _desc)
        if multi:
            if lines:
                lines.extend(self._format_block(padding + ' * ', field))
            else:
                lines.extend(self._format_block(field_type + ' * ', field))
        else:
            lines.extend(self._format_block(field_type + ' ', field))
    if lines and lines[-1]:
        lines.append('')
    return lines

def _get_current_indent(self, peek_ahead: int = 0) -> int:
    line = self._lines.get(peek_ahead)
    while line is not self._lines.sentinel:
        if line:
            return self._get_indent(line)
        peek_ahead += 1
        line = self._lines.get(peek_ahead)
    return 0

def _get_indent(self, line: str) -> int:
    for i, s in enumerate(line):
        if not s.isspace():
            return i
    return len(line)

def _get_initial_indent(self, lines: list[str]) -> int:
    for line in lines:
        if line:
            return self._get_indent(line)
    return 0

def _get_min_indent(self, lines: list[str]) -> int:
    min_indent = None
    for line in lines:
        if line:
            indent = self._get_indent(line)
            if min_indent is None or indent < min_indent:
                min_indent = indent
    return min_indent or 0

def _indent(self, lines: list[str], n: int = 4) -> list[str]:
    return [(' ' * n) + line for line in lines]

def _is_indented(self, line: str, indent: int = 1) -> bool:
    for i, s in enumerate(line):
        if i >= indent:
            return True
        elif not s.isspace():
            return False
    return False

def _is_list(self, lines: list[str]) -> bool:
    if not lines:
        return False
    if _bullet_list_regex.match(lines[0]):
        return True
    if _enumerated_list_regex.match(lines[0]):
        return True
    if len(lines) < 2 or lines[0].endswith('::'):
        return False
    indent = self._get_indent(lines[0])
    next_indent = indent
    for line in lines[1:]:
        if line:
            next_indent = self._get_indent(line)
            break
    return next_indent > indent

